<?php
namespace App\Http\Controllers; use App\Domain\Capabilities\{CapabilityIndexViewData,CapabilityViewData}; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; class PublicCapabilityController extends Controller { public function index(Request $request,CapabilityIndexViewData $data):View{$category=$request->validate(['category'=>['nullable','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/'],'page'=>['nullable','integer','min:1']])['category']??null;$items=$data->get($category,max(1,$request->integer('page',1)));if($items['invalid'])abort(404);return view('capabilities.index',['capabilities'=>$items,'selectedCategory'=>$category]+app(PublicSiteController::class)->sharedViewData($request));} public function show(Request $request,string $capability,CapabilityViewData $data):View{$item=$data->published($capability);if(!$item)abort(404);return view('capabilities.show',['capability'=>$item,'preview'=>false]+app(PublicSiteController::class)->sharedViewData($request));} }
